PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
SELECT ?o ?o2 WHERE {
  ?z a brick:Zone ; rdfs:label "DataCenter_bot_ZN_6" .
}

PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
