SELECT ?z ?ztype WHERE {
  ?z rdfs:label "DataCenter_bot_ZN_6" .
  OPTIONAL { ?z a ?ztype }
}

PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
PREFIX ref: <http://w3.org/ns/ldp>#
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?p ?ptype ?tsid ?pointuri ?unit WHERE {
  ?p brick:hasPoint ; rdfs:label "DataCenter_bot_ZN_6" .
  ?p a ?ptype .
  OPTIONAL { ?p ref:hasTimeseriesId ?tsid }
  OPTIONAL { ?p ref:hasExternalReference ?pointuri }
  OPTIONAL { ?p brick:units ?unit }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?p ?plabel WHERE {
  ?z rdfs:label "DataCenter_bot_ZN_6" .
  ?z a ?a .
  ?z ?p ?p .
}

SELECT ?z ?p WHERE {
  ?z rdfs:label "DataCenter_bot_ZN_6" .
  ?z ?p ?obj .
}

SELECT ?z ?obj WHERE {
  ?z rdfs:label "DataCenter_bot_ZN_6" .
  ?z https://brickschema.org/schema/Brick#hasPoint ?obj .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?obj WHERE {
  ?z rdfs:label "DataCenter_bot_ZN_6" .
  ?z brick:hasPoint ?obj .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?p ?tsid ?unit ?q WHERE {
  ?z rdfs:label "DataCenter_bot_ZN_6" .
  ?z a ?ztype .
  ?z brick:hasPoint ?p .
  ?p rdfs:label ?plabel .
  FILTER(CONTSTR(STR(?plabel), "Zone_F2_Z07"))
  OPTIONAL { ?p ref:hasTimeseriesId ?tsid }
  OPTIONAL { ?p brick:units ?unit }
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?p ?tsid ?unit WHERE {
  ?z rdfs:label "DataCenter_bot_ZN_6" .
  ?z a ?ztype .
  ?z brick:hasPoint ?p .
  ?p rdfs:label ?plabel .
  OPTIONAL { ?p ref:hasTimeseriesId ?tsid }
  OPTIONAL { ?p brick:units ?unit }
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?p ?tsid ?unit WHERE {
  ?z rdfs:label "DataCenter_bot_ZN_6" .
  ?z a ?ztype .
  ?z brick:hasPoint ?p .
  ?p rdfs:label ?plabel .
  ?p ref:hasTimeseriesId ?tsid .
  OPTIONAL { ?p brick:units ?unit }
}

SELECT ?p ?pred ?obj WHERE {
  ?z rdfs:label "DataCenter_bot_ZN_6" .
  ?z a ?ztype .
  ?z brick:hasPoint ?p .
}

